"""Shared validation and publication helpers for checkpoint utilities.

The public checkpoint commands deliberately keep their dependency imports lazy,
but the file-format and publication contracts are shared by merge and soup.
"""

from __future__ import annotations

import hashlib
import json
import math
import os
import shutil
import tempfile
from collections.abc import Iterator, Mapping
from contextlib import contextmanager
from pathlib import Path
from typing import Any

# These fields are generated by different Transformers versions or by the
# location from which a model was loaded.  They do not describe model
# semantics, so allowing them to differ keeps independently saved copies of
# one base model compatible without weakening the actual config comparison.
CONFIG_VOLATILE_FIELDS = ("_name_or_path", "_commit_hash", "transformers_version")

# Include the common fast, SentencePiece, and processor/tokenizer artifacts.
# The set is intentionally broader than the files emitted by one tokenizer
# implementation: dropping a vocabulary, merge table, chat template, or
# custom tokenizer code would make a published soup incomplete.
TOKENIZER_EXACT_FILES = frozenset(
    {
        "added_tokens.json",
        "chat_template.jinja",
        "feature_extractor_config.json",
        "generation_config.json",
        "image_processor_config.json",
        "preprocessor_config.json",
        "processor_config.json",
        "special_tokens_map.json",
        "spiece.model",
        "tokenizer.json",
        "tokenizer.model",
        "tokenizer_config.json",
        "vocab.json",
        "vocab.txt",
        "merges.txt",
    }
)
TOKENIZER_PREFIXES = (
    "added_tokens.",
    "chat_template.",
    "feature_extractor",
    "image_processor",
    "merges.",
    "normalizer.",
    "preprocessor",
    "processor",
    "sentencepiece",
    "special_tokens_map.",
    "spiece.",
    "tokenizer",
    "vocab.",
)
TOKENIZER_PAYLOAD_EXACT_FILES = frozenset(
    {
        "spiece.model",
        "tokenizer.json",
        "tokenizer.model",
        "vocab.json",
        "vocab.txt",
    }
)
TOKENIZER_PAYLOAD_PREFIXES = ("sentencepiece", "spiece.", "tokenizer.", "vocab.")
TOKENIZER_CODE_SUFFIXES = (".py", ".pyc", ".pyo", ".pyi")

# Safetensors dtype names and their storage width.  Unknown dtypes are
# rejected instead of guessed so shard sizing and dtype parity remain exact.
DTYPE_BITS = {
    "BOOL": 8,
    "U8": 8,
    "U16": 16,
    "U32": 32,
    "U64": 64,
    "I8": 8,
    "I16": 16,
    "I32": 32,
    "I64": 64,
    "F8_E4M3": 8,
    "F8_E5M2": 8,
    "F8_E4M3FNUZ": 8,
    "F8_E5M2FNUZ": 8,
    "F16": 16,
    "BF16": 16,
    "F32": 32,
    "F64": 64,
}


def _reject_json_constant(value: str) -> None:
    raise ValueError(f"non-finite JSON value is not allowed: {value}")


def read_json(path: Path) -> Any:
    """Read JSON while rejecting non-standard NaN/Infinity constants."""

    try:
        return json.loads(path.read_text(encoding="utf-8"), parse_constant=_reject_json_constant)
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as error:
        raise ValueError(f"invalid JSON file: {path}") from error


def read_mapping(path: Path) -> Mapping[str, Any]:
    value = read_json(path)
    if not isinstance(value, dict):
        raise ValueError(f"expected a JSON object: {path}")  # noqa: TRY004
    return value


def semantic_config(path: Path) -> dict[str, Any]:
    """Return a strict, portable semantic config for a seq2seq checkpoint."""

    config_path = path / "config.json"
    if not config_path.is_file():
        raise FileNotFoundError(f"config.json not found in {path}")
    config = dict(read_mapping(config_path))
    model_type = config.get("model_type")
    if not isinstance(model_type, str) or not model_type:
        raise ValueError(f"model config has no model_type: {config_path}")
    if config.get("is_encoder_decoder") is not True:
        raise ValueError(
            f"model config must set is_encoder_decoder=true; refusing incompatible model: {config_path}"
        )
    for field in CONFIG_VOLATILE_FIELDS:
        config.pop(field, None)
    return config


def file_digest(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def relevant_metadata_files(path: Path) -> tuple[Path, ...]:
    """List model/tokenizer metadata that must survive merge and soup."""

    result = []
    for candidate in sorted(path.iterdir()):
        if not candidate.is_file():
            continue
        name = candidate.name
        if (
            name == "config.json"
            or name in TOKENIZER_EXACT_FILES
            or any(name.startswith(prefix) for prefix in TOKENIZER_PREFIXES)
            or name.endswith(".py")
        ):
            result.append(candidate)
    return tuple(result)


def tokenizer_fingerprint(path: Path) -> dict[str, str]:
    metadata_files = relevant_metadata_files(path)
    if not any(
        candidate.name in TOKENIZER_PAYLOAD_EXACT_FILES
        or (
            not candidate.name.lower().endswith(TOKENIZER_CODE_SUFFIXES)
            and any(candidate.name.startswith(prefix) for prefix in TOKENIZER_PAYLOAD_PREFIXES)
        )
        for candidate in metadata_files
    ):
        raise FileNotFoundError(f"no tokenizer payload found in {path}")
    files = {
        candidate.name: file_digest(candidate)
        for candidate in metadata_files
        if candidate.name != "config.json" and candidate.suffix != ".py"
    }
    if not files:
        raise FileNotFoundError(f"no tokenizer files found in {path}")
    # Custom model code can be present without any tokenizer artifact.  Keep
    # that code in the fingerprint when a tokenizer exists, but do not let it
    # make an otherwise incomplete checkpoint look loadable.
    files.update(
        {
            candidate.name: file_digest(candidate)
            for candidate in metadata_files
            if candidate.name.endswith(".py")
        }
    )
    return files


def copy_relevant_metadata(
    source: Path, destination: Path, *, exclude_names: set[str] | frozenset[str] = frozenset()
) -> None:
    for candidate in relevant_metadata_files(source):
        if candidate.name in exclude_names:
            continue
        shutil.copy2(candidate, destination / candidate.name)


def _safe_weight_path(model_dir: Path, filename: str) -> Path:
    if not filename or Path(filename).is_absolute():
        raise ValueError(f"invalid safetensors shard filename: {filename!r}")
    candidate = (model_dir / filename).resolve()
    root = model_dir.resolve()
    try:
        candidate.relative_to(root)
    except ValueError as error:
        raise ValueError(f"safetensors shard escapes model directory: {filename}") from error
    if not candidate.is_file():
        raise FileNotFoundError(
            f"safetensors shard is outside model directory or missing: {filename}"
        )
    return candidate


def weight_map(model_dir: Path) -> dict[str, Path]:
    """Read and validate a single or indexed safetensors checkpoint."""

    from safetensors import safe_open

    index_path = model_dir / "model.safetensors.index.json"
    single = model_dir / "model.safetensors"
    if index_path.is_file() and single.is_file():
        raise ValueError(
            f"checkpoint contains both an index and an unindexed weight file: {model_dir}"
        )
    if index_path.is_file():
        index = read_mapping(index_path)
        mapping = index.get("weight_map")
        if not isinstance(mapping, dict) or not mapping:
            raise ValueError(f"invalid safetensors index: {index_path}")
        result: dict[str, Path] = {}
        for key, filename in mapping.items():
            if not isinstance(key, str) or not key:
                raise ValueError(f"invalid tensor key in safetensors index: {index_path}")
            if not isinstance(filename, str):
                raise ValueError(  # noqa: TRY004
                    f"invalid shard filename for tensor {key}: {index_path}"
                )
            result[key] = _safe_weight_path(model_dir, filename)
    elif single.is_file():
        result = {}
        with safe_open(single, framework="pt", device="cpu") as handle:
            for key in handle.keys():  # noqa: SIM118
                result[key] = single.resolve()
        if not result:
            raise ValueError(f"safetensors file has no tensors: {single}")
    else:
        raise FileNotFoundError(f"model.safetensors or its index not found in {model_dir}")

    expected_by_file: dict[Path, set[str]] = {}
    for key, filename in result.items():
        expected_by_file.setdefault(filename, set()).add(key)
    if index_path.is_file():
        actual_weight_files = {
            candidate.resolve()
            for candidate in model_dir.rglob("*.safetensors")
            if candidate.is_file()
        }
        extra_weight_files = actual_weight_files.difference(expected_by_file)
        if extra_weight_files:
            raise ValueError(
                "safetensors index leaves unreferenced weight files: "
                f"{sorted(str(path) for path in extra_weight_files)}"
            )
    seen: set[str] = set()
    for filename, expected in expected_by_file.items():
        with safe_open(filename, framework="pt", device="cpu") as handle:
            actual = set(handle.keys())
        if actual != expected:
            missing = sorted(expected - actual)
            extra = sorted(actual - expected)
            raise ValueError(
                f"safetensors index does not exactly describe {filename}"
                f" (missing={missing}, extra={extra})"
            )
        overlap = seen.intersection(actual)
        if overlap:
            raise ValueError(f"duplicate tensor keys across safetensors shards: {sorted(overlap)}")
        seen.update(actual)
    return result


def tensor_metadata(
    tensors: Mapping[str, Path],
) -> dict[str, tuple[str, tuple[int, ...], int]]:
    """Return dtype, shape, and exact storage bytes for each tensor."""

    from safetensors import safe_open

    result: dict[str, tuple[str, tuple[int, ...], int]] = {}
    by_file: dict[Path, list[str]] = {}
    for key, filename in tensors.items():
        by_file.setdefault(filename, []).append(key)
    for filename, keys in by_file.items():
        with safe_open(filename, framework="pt", device="cpu") as handle:
            for key in keys:
                view = handle.get_slice(key)
                dtype = str(view.get_dtype())
                bits = DTYPE_BITS.get(dtype)
                if bits is None:
                    raise ValueError(f"unsupported safetensors dtype {dtype!r} for tensor {key}")
                shape = tuple(int(dimension) for dimension in view.get_shape())
                count = math.prod(shape) if shape else 1
                result[key] = (dtype, shape, count * bits // 8)
    first_weight = next(iter(tensors.values()))
    index_path = next(
        (
            directory / "model.safetensors.index.json"
            for directory in (first_weight.parent, *first_weight.parents)
            if (directory / "model.safetensors.index.json").is_file()
        ),
        None,
    )
    if index_path is not None:
        index = read_mapping(index_path)
        index_metadata = index.get("metadata")
        if index_metadata is not None:
            if not isinstance(index_metadata, dict):
                raise ValueError(f"invalid safetensors index metadata: {index_path}")
            declared_size = index_metadata.get("total_size")
            if declared_size is not None:
                if isinstance(declared_size, bool) or not isinstance(declared_size, int):
                    raise ValueError(f"invalid safetensors index total_size: {index_path}")
                actual_size = sum(value[2] for value in result.values())
                if declared_size != actual_size:
                    raise ValueError(
                        f"safetensors index total_size {declared_size} does not match "
                        f"tensor bytes {actual_size}: {index_path}"
                    )
    return result


def check_finite_tensor(tensor: Any, label: str) -> None:
    """Fail closed on NaN/Infinity in a floating tensor."""

    if not getattr(tensor, "is_floating_point", lambda: False)():
        return
    import torch

    try:
        finite = torch.isfinite(tensor).all()
    except RuntimeError:
        finite = torch.isfinite(tensor.float()).all()
    if not bool(finite.item()):
        raise ValueError(f"non-finite tensor: {label}")


def check_finite_state(model: Any, label: str) -> None:
    for name, tensor in model.state_dict().items():
        check_finite_tensor(tensor, f"{label}:{name}")


@contextmanager
def staged_output(destination: str | Path) -> Iterator[Path]:
    """Stage a new directory and publish it without replacing an existing one."""

    destination = Path(destination)
    # ``Path.exists()`` is false for a dangling symlink.  Treat every
    # directory entry as occupied so a failed or malicious output path can
    # never be replaced during the final rename.
    if os.path.lexists(destination):
        raise FileExistsError(f"refusing to overwrite output directory: {destination}")
    destination.parent.mkdir(parents=True, exist_ok=True)
    lock = destination.with_name(f".{destination.name}.lock")
    try:
        lock.mkdir()
    except FileExistsError as error:
        raise FileExistsError(
            f"output directory is already being created: {destination}"
        ) from error
    try:
        if os.path.lexists(destination):
            raise FileExistsError(f"refusing to overwrite output directory: {destination}")
        with tempfile.TemporaryDirectory(
            prefix=f".{destination.name}.", dir=destination.parent
        ) as root:
            temporary = Path(root) / "model"
            temporary.mkdir()
            yield temporary
            if os.path.lexists(destination):
                raise FileExistsError(f"refusing to overwrite output directory: {destination}")
            # All compliant writers hold the lock.  The preflight checks and
            # this final existence check prevent ordinary races without ever
            # replacing an already-existing output selected by the caller.
            os.rename(temporary, destination)
    finally:
        shutil.rmtree(lock, ignore_errors=True)
